const clamp = (value: number, minimum = 0, maximum = 1) =>
  Math.min(maximum, Math.max(minimum, value));

const lerp = (from: number, to: number, amount: number) =>
  from + (to - from) * amount;

const hashString = (value: string) => {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
};

const unitFromHash = (hash: number, offset = 0) => {
  const value = Math.sin((hash + offset * 1013) * 12.9898) * 43758.5453;
  return value - Math.floor(value);
};

const hexToRgb = (hex: string) => {
  const clean = hex.replace('#', '');
  return {
    r: Number.parseInt(clean.slice(0, 2), 16),
    g: Number.parseInt(clean.slice(2, 4), 16),
    b: Number.parseInt(clean.slice(4, 6), 16),
  };
};

const mixHex = (from: string, to: string, amount: number) => {
  const a = hexToRgb(from);
  const b = hexToRgb(to);
  const t = clamp(amount);
  const channel = (start: number, end: number) =>
    Math.round(lerp(start, end, t)).toString(16).padStart(2, '0');
  return `#${channel(a.r, b.r)}${channel(a.g, b.g)}${channel(a.b, b.b)}`;
};

const mapRange = (
  frame: number,
  input: readonly number[],
  output: readonly number[],
  easing?: (value: number) => number,
) =>
  interpolate(frame, input, output, {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing,
  });

const triangleWave = (frame: number, period: number, phase = 0) => {
  const unit = (((frame + phase) % period) + period) % period / period;
  return unit < 0.5 ? unit * 4 - 1 : 3 - unit * 4;
};

const COUNTRY_META = VERIFIED_COUNTRY_PATHS.map((country) => {
  const hash = hashString(`${country.id}-${country.name}`);
  return {
    ...country,
    hash,
    tint: unitFromHash(hash, 1),
    infection: unitFromHash(hash, 2),
    shimmer: unitFromHash(hash, 3),
  };
});

const PARTICLES = Array.from({length: 3600}, (_, index) => {
  const hash = hashString(`digital-speck-${index}`);
  const radiusSeed = unitFromHash(hash, 3);
  return {
    x: 16 + unitFromHash(hash, 1) * 1888,
    y: 12 + unitFromHash(hash, 2) * 1056,
    radius:
      radiusSeed > 0.9
        ? 3.15 + ((radiusSeed - 0.9) / 0.1) * 0.65
        : 0.7 + (radiusSeed / 0.9) * 0.8,
    phase: unitFromHash(hash, 4) * Math.PI * 2,
    speed: 0.168 + unitFromHash(hash, 5) * 0.206,
    active: unitFromHash(hash, 6) > 0.89,
    group: index % 4,
    large: radiusSeed > 0.9,
  };
});

const ACTIVE_PARTICLES = PARTICLES.filter((particle) => particle.active);
const STABLE_PARTICLE_PATHS = Array.from({length: 8}, (_, bucket) => {
  const group = bucket % 4;
  const large = bucket >= 4;
  return {
    group,
    large,
    path: PARTICLES.filter(
      (particle) => !particle.active && particle.group === group && particle.large === large,
    )
      .map(({x, y, radius}) => {
        if (!large) {
          const width = 2.2 + radius * 0.15;
          const height = 0.9;
          return `M${(x - width / 2).toFixed(2)},${(y - height / 2).toFixed(2)}h${width.toFixed(2)}v${height.toFixed(2)}h-${width.toFixed(2)}Z`;
        }
        const stableRadius = radius < 3.5 ? radius * 0.72 : radius;
        return `M${(x - stableRadius).toFixed(2)},${y.toFixed(2)}a${stableRadius.toFixed(2)},${stableRadius.toFixed(2)} 0 1,0 ${(stableRadius * 2).toFixed(2)},0a${stableRadius.toFixed(2)},${stableRadius.toFixed(2)} 0 1,0 -${(stableRadius * 2).toFixed(2)},0`;
      })
      .join(''),
  };
});

const MAP_BLOCKS = Array.from({length: 46}, (_, index) => {
  const hash = hashString(`map-block-${index}`);
  return {
    x: 80 + unitFromHash(hash, 1) * 1760,
    y: 180 + unitFromHash(hash, 2) * 680,
    size: 10 + unitFromHash(hash, 3) * 40,
    phase: unitFromHash(hash, 4) * Math.PI * 2,
  };
});

