const HudText: React.FC<{
  frame: number;
  crisis: number;
  side: 'left' | 'right';
}> = ({frame, crisis, side}) => {
  const rows = Array.from({length: side === 'left' ? 12 : 15}, (_, index) => {
    const code = Math.floor((frame * (17 + index) + index * 7919) % 999999);
    return `${String(index + 1).padStart(2, '0')}  ${code
      .toString()
      .padStart(6, '0')}  ${index % 3 === 0 ? 'SYNC' : index % 3 === 1 ? 'TRACE' : 'NODE'}`;
  });
  const color = mixHex('#4deaff', '#ff536c', crisis);
  const yShift = -((frame * 0.42) % 18);

  return (
    <div
      style={{
        position: 'absolute',
        top: side === 'left' ? 372 : 618,
        [side]: 34,
        width: side === 'left' ? 284 : 236,
        height: side === 'left' ? 246 : 300,
        overflow: 'hidden',
        opacity: 0.38 + crisis * 0.18,
        fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace',
        fontSize: 12,
        lineHeight: '18px',
        letterSpacing: 1.6,
        color,
        textShadow: `0 0 10px ${color}`,
      }}
    >
      <div style={{transform: `translateY(${yShift}px)`}}>
        {[...rows, ...rows.slice(0, 2)].map((row, index) => (
          <div key={`${side}-${index}`} style={{whiteSpace: 'pre'}}>
            {row}
          </div>
        ))}
      </div>
    </div>
  );
};

