const DigitalBackground: React.FC<{
  frame: number;
  crisis: number;
}> = ({frame, crisis}) => {
  const cold = '#06152c';
  const hot = '#210209';
  const base = mixHex(cold, hot, crisis);
  const accent = mixHex('#19c8ff', '#ff183e', crisis);
  const scanY = ((frame * 4.2) % 1280) - 120;

  return (
    <AbsoluteFill style={{backgroundColor: base, overflow: 'hidden'}}>
      <div
        style={{
          position: 'absolute',
          inset: -120,
          backgroundImage: `
            linear-gradient(${mixHex('#173f62', '#761328', crisis)}33 1px, transparent 1px),
            linear-gradient(90deg, ${mixHex('#173f62', '#761328', crisis)}33 1px, transparent 1px),
            linear-gradient(${mixHex('#0b223b', '#3e0812', crisis)}77 1px, transparent 1px),
            linear-gradient(90deg, ${mixHex('#0b223b', '#3e0812', crisis)}77 1px, transparent 1px)
          `,
          backgroundSize: '96px 96px, 96px 96px, 24px 24px, 24px 24px',
          backgroundPosition: `${frame * 0.18}px ${frame * 0.09}px`,
          opacity: 0.5,
          transform: `rotate(-0.22deg) scale(1.03)`,
        }}
      />

      <div
        style={{
          position: 'absolute',
          left: -160,
          top: scanY,
          width: 2240,
          height: 150,
          background: `linear-gradient(180deg, transparent, ${accent}15, ${accent}32, transparent)`,
          filter: 'blur(8px)',
          mixBlendMode: 'screen',
        }}
      />

      <svg width="1920" height="1080" viewBox="0 0 1920 1080" style={{position: 'absolute', inset: 0}}>
        {STABLE_PARTICLE_PATHS.map(({path, group, large}) => (
          <path
            key={`stable-${large ? 'large' : 'small'}-${group}`}
            d={path}
            fill={accent}
            opacity={
              ((large ? 0.42 : 0.82) +
                Math.sin(frame * 0.16 + group * 1.7) * (large ? 0.052 : 0.105)) *
              (0.86 + crisis * 0.14)
            }
            transform={`translate(${triangleWave(frame, 180, group * 45) * 0.73} 0)`}
          />
        ))}
        {ACTIVE_PARTICLES.map((particle, index) => {
          const wave = 0.5 + 0.5 * Math.sin(frame * particle.speed + particle.phase);
          const opacity = (0.012 + Math.pow(wave, 4) * 0.9) * (0.78 + crisis * 0.22);
          return (
            <circle
              key={index}
              cx={particle.x}
              cy={particle.y}
              r={particle.radius}
              fill={accent}
              opacity={opacity}
            />
          );
        })}
      </svg>

      <div
        style={{
          position: 'absolute',
          inset: 0,
          background: `
            radial-gradient(circle at 50% 54%, ${mixHex('#073963', '#700a19', crisis)}66 0%, transparent 47%),
            radial-gradient(circle at 50% 50%, transparent 48%, ${mixHex('#01040b', '#080003', crisis)}dd 100%)
          `,
        }}
      />
    </AbsoluteFill>
  );
};

const NetworkOverlay: React.FC<{
  frame: number;
  fps: number;
  activation: number;
  crisis: number;
}> = ({frame, fps, activation, crisis}) => {
  const startFrame = Math.round(5.3 * fps);
  const glow = mixHex('#50f6ff', '#ffb21c', crisis);
  const lineColor = mixHex('#7ff8ff', '#ffe2a1', crisis);

  return (
    <g opacity={activation}>
      <defs>
        <filter id="node-glow" x="-80%" y="-80%" width="260%" height="260%">
          <feGaussianBlur stdDeviation="8" result="blur" />
          <feMerge>
            <feMergeNode in="blur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>

      <g fill="none" stroke={lineColor} strokeWidth="2.2" opacity={0.76}>
        {ROUTES.map((route, index) => {
          const from = NODES[route.from];
          const to = NODES[route.to];
          const distance = Math.hypot(to.x - from.x, to.y - from.y);
          const raw = ((frame - startFrame + route.phase) % 108 + 108) % 108;
          const draw = raw < 36 ? raw / 36 : raw < 72 ? 1 - (raw - 36) / 36 : 0;
          const packet = clamp(raw / 72);
          const routeOpacity = draw > 0 ? 0.22 + draw * 0.78 : 0;
          return (
            <g key={index} opacity={routeOpacity}>
              <line
                x1={from.x}
                y1={from.y}
                x2={to.x}
                y2={to.y}
                strokeDasharray={`${distance} ${distance}`}
                strokeDashoffset={distance * (1 - draw)}
              />
              <circle
                cx={lerp(from.x, to.x, packet)}
                cy={lerp(from.y, to.y, packet)}
                r={4 + draw * 3}
                fill={lineColor}
                stroke="none"
                filter="url(#node-glow)"
              />
            </g>
          );
        })}
      </g>

      <g filter="url(#node-glow)">
        {NODES.map((node, index) => {
          const pulse = 0.5 + 0.5 * Math.sin((frame + node.phase) * 0.16);
          const pulse2 = 0.5 + 0.5 * Math.sin((frame + node.phase * 2.4) * 0.074);
          const ringRadius = 20 + pulse * 17;
          const wedgeAngle = frame * (1.45 + (index % 3) * 0.28) + node.phase * 7;
          return (
            <g key={node.label} transform={`translate(${node.x} ${node.y})`}>
              <circle r={11 + pulse * 8} fill={glow} opacity={0.32 + pulse * 0.46} />
              <circle r="6" fill="#fff4c9" opacity={0.72 + pulse * 0.28} />
              <circle
                r={ringRadius}
                fill="none"
                stroke={glow}
                strokeWidth={2 + pulse2 * 2}
                opacity={0.25 + pulse2 * 0.62}
              />
              <circle
                r={32 + pulse2 * 9}
                fill="none"
                stroke={glow}
                strokeWidth="1.4"
                strokeDasharray="7 11"
                opacity={0.3 + pulse * 0.34}
                transform={`rotate(${-wedgeAngle * 0.62})`}
              />
              <g transform={`rotate(${wedgeAngle})`} opacity={0.62 + pulse * 0.34}>
                <path d="M0 0L42 -7A43 43 0 0 1 42 7Z" fill={glow} />
                <line x1="0" y1="0" x2="58" y2="0" stroke="#fff1be" strokeWidth="2" />
              </g>
              <text
                x="14"
                y="-17"
                fill="#fff5d8"
                fontFamily="ui-monospace, monospace"
                fontSize="10"
                letterSpacing="1.5"
                opacity={0.34 + pulse * 0.45}
              >
                {node.label}
              </text>
            </g>
          );
        })}
      </g>
    </g>
  );
};

const WorldMap: React.FC<{
  frame: number;
  fps: number;
  durationInFrames: number;
  crisis: number;
}> = ({frame, fps, durationInFrames, crisis}) => {
  const progress = frame / Math.max(1, durationInFrames - 1);
  const cameraX = lerp(-18, 24, progress) + Math.sin(frame / 73) * 7;
  const cameraY = lerp(8, -14, progress) + Math.cos(frame / 101) * 5;
  const cameraScale = 1.018 + progress * 0.042 + Math.sin(frame / 164) * 0.006;
  const networkActivation = mapRange(frame, [Math.round(5.05 * fps), Math.round(5.5 * fps)], [0, 1]);
  const scanX = ((frame * 7.4) % 2240) - 180;
  const mapAccent = mixHex('#21dfff', '#ff153f', crisis);

  return (
    <div
      style={{
        position: 'absolute',
        inset: 0,
        transformOrigin: '50% 50%',
        transform: `translate3d(${cameraX}px, ${cameraY}px, 0) scale(${cameraScale})`,
      }}
    >
      <svg
        width="1920"
        height="1080"
        viewBox="0 0 1920 1080"
        style={{position: 'absolute', inset: 0, overflow: 'visible'}}
      >
        <defs>
          <filter id="map-glow" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="4.5" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
          <linearGradient id="map-scan" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0" stopColor={mapAccent} stopOpacity="0" />
            <stop offset="0.5" stopColor="#ffffff" stopOpacity="0.5" />
            <stop offset="1" stopColor={mapAccent} stopOpacity="0" />
          </linearGradient>
        </defs>

        <g transform="translate(57 -54) scale(0.94 1.1)">
          <g filter="url(#map-glow)">
            {COUNTRY_META.map((country) => {
              const infectionStart = Math.round((4.18 + country.infection * 1.18) * fps);
              const infection = mapRange(frame, [infectionStart, infectionStart + 22], [0, 1], Easing.inOut(Easing.cubic));
              const shimmer = 0.5 + 0.5 * Math.sin(frame * (0.028 + country.shimmer * 0.026) + country.tint * 8);
              const cold = mixHex('#0c73d8', '#37e5ff', 0.24 + country.tint * 0.76);
              const hot = mixHex('#861022', '#ff1748', 0.18 + country.tint * 0.82);
              const fill = mixHex(cold, hot, infection);
              return (
                <path
                  key={country.id}
                  d={country.d}
                  fill={fill}
                  fillOpacity={0.64 + shimmer * 0.24}
                  stroke={mixHex('#60f4ff', '#ff3153', infection)}
                  strokeOpacity={0.38 + shimmer * 0.28}
                  strokeWidth="1.25"
                  vectorEffect="non-scaling-stroke"
                />
              );
            })}
          </g>

          <g style={{mixBlendMode: 'screen'}}>
            {MAP_BLOCKS.map((block, index) => {
              const blink = 0.5 + 0.5 * Math.sin(frame * 0.052 + block.phase);
              return (
                <rect
                  key={index}
                  x={block.x}
                  y={block.y}
                  width={block.size}
                  height={block.size}
                  fill={mapAccent}
                  opacity={0.03 + blink * 0.13}
                />
              );
            })}
          </g>

          <rect
            x={scanX}
            y="-120"
            width="150"
            height="1280"
            fill="url(#map-scan)"
            opacity={0.16 + crisis * 0.08}
            transform={`skewX(-12)`}
            style={{mixBlendMode: 'screen'}}
          />

          <NetworkOverlay
            frame={frame}
            fps={fps}
            activation={networkActivation}
            crisis={crisis}
          />
        </g>
      </svg>
    </div>
  );
};

