const CyberPanel: React.FC<{
  frame: number;
  fps: number;
  durationInFrames: number;
  crisis: number;
}> = ({frame, fps, durationInFrames, crisis}) => {
  const f = (seconds: number) => Math.round(seconds * fps);
  const progress = frame / Math.max(1, durationInFrames - 1);
  const entrance = mapRange(frame, [f(0.25), f(0.55), f(0.72)], [0.16, 1.035, 1], Easing.out(Easing.cubic));
  const opacity = mapRange(frame, [f(0.23), f(0.36)], [0, 1]);
  const driftX = -lerp(-18, 24, progress) * 0.12 + Math.sin(frame / 89) * 3.4;
  const driftY = -lerp(8, -14, progress) * 0.11 + Math.cos(frame / 113) * 2.6;
  const tiltX = Math.sin(frame / 122) * 0.46;
  const tiltY = Math.cos(frame / 96) * 0.68;
  const panelHot = mixHex('#d00a4e', '#b50727', crisis);
  const panelDeep = mixHex('#450421', '#320207', crisis);
  const outline = mixHex('#ff70ac', '#ff4d62', crisis);
  const sheenX = ((frame * 8.8) % 1400) - 430;
  const glitch = mapRange(frame, [f(6.38), f(6.48), f(6.64), f(6.74)], [0, 1, 0.72, 0]);

  return (
    <>
      <div
        style={{
          position: 'absolute',
          left: '50%',
          top: '49.5%',
          width: 906,
          height: 494,
          marginLeft: -453,
          marginTop: -247,
          opacity,
          transformOrigin: '50% 50%',
          transform: `translate3d(${driftX}px, ${driftY}px, 0) perspective(1600px) rotateX(${tiltX}deg) rotateY(${tiltY}deg) scale(${entrance})`,
        }}
      >
        <div
          style={{
            position: 'absolute',
            inset: 0,
            clipPath: 'polygon(3.4% 0, 96.4% 0, 100% 7%, 100% 89%, 96% 100%, 4% 100%, 0 89%, 0 8%)',
            background: `linear-gradient(150deg, ${outline}, ${panelHot} 19%, ${panelDeep} 88%)`,
            opacity: 0.36,
            filter: 'drop-shadow(0 24px 42px rgba(0,0,0,.5)) drop-shadow(0 0 24px rgba(255,18,77,.45))',
          }}
        />
        <div
          style={{
            position: 'absolute',
            inset: 3,
            clipPath: 'polygon(3.2% 0, 96.2% 0, 100% 7%, 100% 89%, 96% 100%, 4% 100%, 0 89%, 0 8%)',
            background: `
              linear-gradient(145deg, rgba(255,255,255,.16), transparent 31%),
              linear-gradient(180deg, ${panelHot}a8, ${panelDeep}b8)
            `,
            border: '1px solid rgba(255,220,230,.22)',
            overflow: 'hidden',
          }}
        >
          <div
            style={{
              position: 'absolute',
              top: -120,
              left: sheenX,
              width: 240,
              height: 760,
              transform: 'skewX(-19deg)',
              background: 'linear-gradient(90deg, transparent, rgba(255,255,255,.2), transparent)',
              opacity: 0.44,
              mixBlendMode: 'screen',
            }}
          />
          <PanelContent frame={frame} fps={fps} crisis={crisis} />
        </div>

        <div
          style={{
            position: 'absolute',
            right: 20,
            top: 0,
            width: 66,
            height: 48,
            background: 'linear-gradient(180deg, #ff296b, #b6003c)',
            border: '1px solid rgba(255,228,238,.8)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: '#fff',
            fontFamily: 'Arial, sans-serif',
            fontWeight: 900,
            fontSize: 25,
            boxShadow: '0 0 22px rgba(255,29,99,.72)',
          }}
        >
          ×
        </div>
      </div>

      {[
        {top: 340, left: 278, width: 610, height: 74, direction: -1},
        {top: 420, left: 430, width: 990, height: 98, direction: 1},
        {top: 548, left: 565, width: 760, height: 82, direction: -1},
      ].map((slice, index) => (
        <div
          key={index}
          style={{
            position: 'absolute',
            top: slice.top,
            left: slice.left,
            width: slice.width,
            height: slice.height,
            opacity: glitch * (0.5 + index * 0.16),
            transform: `translateX(${slice.direction * glitch * (58 + index * 34)}px)`,
            background: 'linear-gradient(90deg, rgba(14,215,255,.78), rgba(220,255,255,.9), rgba(38,207,255,.5))',
            mixBlendMode: 'screen',
            boxShadow: '0 0 32px rgba(32,231,255,.55)',
          }}
        />
      ))}
    </>
  );
};

export const Motion: React.FC = () => {
  const frame = useCurrentFrame();
  const {fps, durationInFrames} = useVideoConfig();
  const crisis = mapRange(
    frame,
    [Math.round(4.05 * fps), Math.round(5.45 * fps)],
    [0, 1],
    Easing.inOut(Easing.cubic),
  );
  const flash1 = mapRange(
    frame,
    [Math.round(3.95 * fps), Math.round(4.06 * fps), Math.round(4.2 * fps)],
    [0, 1, 0],
  );
  const flash2 = mapRange(
    frame,
    [Math.round(6.38 * fps), Math.round(6.47 * fps), Math.round(6.62 * fps)],
    [0, 1, 0],
  );

  return (
    <div
      style={{
        position: 'absolute',
        inset: 0,
        width: 1920,
        height: 1080,
        backgroundColor: '#02040b',
        overflow: 'hidden',
        color: '#fff',
      }}
    >
      <DigitalBackground frame={frame} crisis={crisis} />
      <WorldMap
        frame={frame}
        fps={fps}
        durationInFrames={durationInFrames}
        crisis={crisis}
      />
      <PeripheralHud frame={frame} crisis={crisis} />
      <CyberPanel
        frame={frame}
        fps={fps}
        durationInFrames={durationInFrames}
        crisis={crisis}
      />

      <div
        style={{
          position: 'absolute',
          inset: 0,
          opacity: flash1 * 0.28 + flash2 * 0.34,
          background: 'radial-gradient(circle at center, #eaffff 0%, #2fe3ff 30%, transparent 72%)',
          mixBlendMode: 'screen',
          pointerEvents: 'none',
        }}
      />

      <div
        style={{
          position: 'absolute',
          inset: 0,
          boxShadow: 'inset 0 0 180px rgba(0,0,0,.82)',
          pointerEvents: 'none',
        }}
      />
    </div>
  );
};
